#ifndef CHECK_PS_FIXTURE_H
#define CHECK_PS_FIXTURE_H
#include <stddef.h>
#include <stdint.h>
#include <string.h>
/* MPEG-1 pack and system headers; independently generated by FFmpeg's MPEG muxer. */
static const uint8_t sample_prefix[]={0,0,1,0xba,0x21,0,1,0,1,0xc3,0x33,0x67,0,0,1,0xbb,0,9,0xc3,0x33,0x67,0,0x21,0xff,0xe0,0xe0,0xe6};
static void sample_pts(uint8_t *p, int prefix, uint64_t v) {
 p[0]=(uint8_t)((prefix<<4)|(((v>>30)&7)<<1)|1);p[1]=(uint8_t)(v>>22);
 p[2]=(uint8_t)((((v>>15)&127)<<1)|1);p[3]=(uint8_t)(v>>7);p[4]=(uint8_t)(((v&127)<<1)|1);
}
static size_t sample_packet(uint8_t *p, int type, size_t count, int stuffing, int both, uint64_t pts) {
 size_t n=0, header=(size_t)stuffing+(both?10:5), size=count+header;
 p[n++]=0;p[n++]=0;p[n++]=1;p[n++]=(uint8_t)type;p[n++]=(uint8_t)(size>>8);p[n++]=(uint8_t)size;
 memset(p+n,255,(size_t)stuffing);n+=(size_t)stuffing;
 sample_pts(p+n,both?3:2,pts);n+=5;
 if(both){sample_pts(p+n,1,pts-3600);n+=5;}
 for(size_t i=0;i<count;i++)p[n+i]=(uint8_t)((i*17+type)%251);
 /* A PES-looking start code is ordinary payload here. */
 if(count>10){p[n+3]=0;p[n+4]=0;p[n+5]=1;p[n+6]=0xe0;}
 return n+count;
}
static size_t sample_fixture(uint8_t *p) {
 memcpy(p,sample_prefix,sizeof sample_prefix);size_t n=sizeof sample_prefix;
 n+=sample_packet(p+n,0xe0,32768,12,1,90000);
 n+=sample_packet(p+n,0xc0,37,0,0,93600);
 memset(p+n,0,8);return n+8;
}
#endif
